\pset pager off
\copy (WITH fam AS (SELECT j.id, j.company, CASE WHEN j.title ~* '\yquant(itative)?\s+(researcher|analyst|strategist|trader)\y|\yalpha\s+research' THEN 'Quantitative Researcher' WHEN j.title ~* '\ydata scientist|\ydata science\y' THEN 'Data Scientist' WHEN j.title ~* '\yai engineer\y|\yapplied ai\y|\yllm engineer\y|\ygen(erative)? ai engineer\y|\yai/ml engineer\y|\yai\y[\w /&-]{0,18}\yengineer\y|\yengineer\y[\w /&-]{0,12}\yai\y|\ysoftware engineer\y[\s,-]*\yai\y|\ydeep learning\y|\ynlp engineer\y|\ycomputer vision engineer\y' THEN 'AI Engineer' WHEN j.title ~* '\ymachine learning engineer\y|\yml engineer\y|\ymlops\y|\yml ops\y|\ymachine learning scientist\y' THEN 'ML Engineer' WHEN j.title ~* '\yanalytics engineer|\yanalytics engineering\y' THEN 'Analytics Engineer' WHEN j.title ~* '\ydata analyst|\ybusiness intelligence\y|\ybi analyst\y' THEN 'Data Analyst' WHEN j.title ~* '\ydata engineer|\ydata platform engineer\y' THEN 'Data Engineer' WHEN j.title ~* '\yresearch scientist\y|\yapplied scientist\y|\yresearch engineer\y' THEN 'Research Scientist' WHEN j.title ~* '\yforward deployed\y|\ysolutions? engineer\y' THEN 'Forward Deployed' END AS family FROM jobs j) SELECT f.family, lower(m.skill) AS phrase, m.required, length(m.evidence) AS len, m.evidence FROM job_skill_mentions m JOIN fam f ON f.id=m.job_id WHERE f.family IS NOT NULL AND m.evidence IS NOT NULL AND length(m.evidence) BETWEEN 40 AND 150 AND lower(m.skill) IN ('rag','agents','llm','llms','prompt engineering','langchain','openai api','fine-tuning','classical machine learning','deep learning','statistical modeling','causal inference','dbt','etl/elt','solutions engineering','quantitative modeling','market microstructure','reinforcement learning','model deployment','bi dashboards','power bi','a/b testing','model training','predictive modeling') ) TO STDOUT WITH CSV HEADER
